add_filter( 'comment_form_default_fields', 'perfectpixel_remove_comment_website_field', 20 );
add_filter( 'preprocess_comment', 'perfectpixel_strip_comment_website', 1 );

function perfectpixel_remove_comment_website_field( $fields ) {
	unset( $fields['url'] );
	return $fields;
}

// Bots post the field directly, so drop it on submission too (logged-in users excluded).
function perfectpixel_strip_comment_website( $commentdata ) {
	if ( empty( $commentdata['user_id'] ) ) {
		$commentdata['comment_author_url'] = '';
	}
	return $commentdata;
}
